package in.recallradar;
import io.swagger.v3.oas.annotations.Operation; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.time.Instant; import java.util.*; import java.util.concurrent.*;
@RestController @RequestMapping("/api/auth") class AuthController { private final AuthService auth; private final InvitationService invites; private final LoginRateLimiter limit; AuthController(AuthService a,InvitationService i,LoginRateLimiter l){auth=a;invites=i;limit=l;}
 @PostMapping("/invitations/accept") TokenResponse acceptInvitation(@Valid @RequestBody AcceptInvitationRequest r){return invites.accept(r);}
 @PostMapping("/register") @ResponseStatus(HttpStatus.CREATED) @Operation(summary="Create the first organization administrator") TokenResponse register(@Valid @RequestBody RegisterRequest r){return auth.register(r);}
 @PostMapping("/login") TokenResponse login(@Valid @RequestBody LoginRequest r,@RequestHeader(value="X-Forwarded-For",required=false) String forwarded){limit.check((forwarded==null?"local":forwarded)+":"+r.email());try{var t=auth.login(r);limit.success((forwarded==null?"local":forwarded)+":"+r.email());return t;}catch(RuntimeException e){limit.fail((forwarded==null?"local":forwarded)+":"+r.email());throw e;}}
 @PostMapping("/refresh") TokenResponse refresh(@Valid @RequestBody RefreshRequest r){return auth.refresh(r);}
 @PostMapping("/logout") @ResponseStatus(HttpStatus.NO_CONTENT) void logout(@Valid @RequestBody RefreshRequest r){auth.logout(r);}
 @PostMapping("/password-reset/request") ResetResponse request(@Valid @RequestBody ResetRequest r){return auth.requestReset(r);}
 @PostMapping("/password-reset/confirm") @ResponseStatus(HttpStatus.NO_CONTENT) void confirm(@Valid @RequestBody ResetConfirmRequest r){auth.reset(r);}
}
@RestController @RequestMapping("/api") class UserController {private final AuthService auth;UserController(AuthService a){auth=a;}@GetMapping("/me") UserResponse me(Authentication a){return auth.current(a.getName());}@GetMapping("/dashboard") Map<String,Object> dashboard(Authentication a){return Map.of("message","Welcome to RecallRadar India", "user",auth.current(a.getName()),"phase",1);}}
@RestController class HealthController {@GetMapping("/actuator/health") Map<String,Object> health(){return Map.of("status","UP","timestamp",Instant.now().toString());}}
@org.springframework.stereotype.Component class LoginRateLimiter {private record Attempt(int failures,Instant reset){} private final ConcurrentHashMap<String,Attempt> attempts=new ConcurrentHashMap<>();void check(String k){var a=attempts.get(k);if(a!=null&&a.reset.isAfter(Instant.now())&&a.failures>=5)throw new org.springframework.web.server.ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,"Too many login attempts. Try again in 15 minutes.");}void fail(String k){attempts.compute(k,(x,a)->a==null||a.reset.isBefore(Instant.now())?new Attempt(1,Instant.now().plusSeconds(900)):new Attempt(a.failures+1,a.reset));}void success(String k){attempts.remove(k);}}
@RestControllerAdvice class ApiErrors {@ExceptionHandler(org.springframework.web.server.ResponseStatusException.class) ResponseEntity<Map<String,Object>> status(org.springframework.web.server.ResponseStatusException e){return ResponseEntity.status(e.getStatusCode()).body(Map.of("error",e.getReason(),"status",e.getStatusCode().value()));}@ExceptionHandler(org.springframework.web.bind.MethodArgumentNotValidException.class) ResponseEntity<Map<String,Object>> validation(org.springframework.web.bind.MethodArgumentNotValidException e){var v=e.getBindingResult().getFieldErrors().stream().collect(java.util.stream.Collectors.toMap(x->x.getField(),x->x.getDefaultMessage(),(a,b)->a));return ResponseEntity.badRequest().body(Map.of("error","Validation failed","fields",v));}@ExceptionHandler(org.springframework.dao.DataIntegrityViolationException.class) ResponseEntity<Map<String,Object>> duplicate(org.springframework.dao.DataIntegrityViolationException e){return ResponseEntity.status(HttpStatus.CONFLICT).body(Map.of("error","A record with those details already exists.","status",409));}}
